import React from 'react';
import member from '../../../assets/member.png'
import President from '../../../assets/president.png';
import Navbar from '../../UI/Navbar/Navbar';
const roles = [
  { title: 'President', name: 'Mr. XYZ Patel', img: President},
  { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
  { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
];

const members = Array(8).fill({
  title: 'Member',
  name: 'Mr. XYZabc Patel',
  img: member,
});

export default function Committee() {
  return (
    <section className="text-center py-10">
      <h2 className="text-2xl font-bold mb-6">Our Committee</h2>
      <div className="flex justify-center mb-4">
        <MemberCard {...roles[0]} />
      </div>
      <div className="flex justify-center space-x-4 mb-4">
        {roles.slice(1).map((role, index) => (
          <MemberCard key={index} {...role} />
        ))}
      </div>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 px-4">
        {members.map((member, index) => (
          <MemberCard key={index} {...member} />
        ))}
      </div>
    </section>
  );
}

function MemberCard({ img, title, name }) {
  return (
    <div className="text-center p-4 border rounded shadow w-32 mx-auto">
      <img src={img} alt={title} className="w-16 h-16 mx-auto rounded-full mb-2" />
      <div className="font-semibold text-sm">{title}</div>
      <div className="text-xs text-gray-600">{name}</div>
    </div>
  );
}
